UStaticMeshComponent* AJamArenaView::AddModel(UStaticMesh* Mesh, UMaterialInterface* Material, const FVector& Location, float Yaw,
	float Size, EArenaPiece Piece)
{
	if (!Mesh)
	{
		return nullptr;
	}
	UStaticMeshComponent* Part = NewObject<UStaticMeshComponent>(this);
	JamShapes::Setup(*Part, Mesh);
	if (Material)
	{
		Part->SetMaterial(0, Material);
	}
	else
	{
		Part->SetMaterial(0, Mesh->GetMaterial(0));
	}
	Part->SetupAttachment(RootComponent);
	Part->RegisterComponent();
	const FBox Bounds = Mesh->GetBoundingBox();
	const float Scale = Size / FMath::Max(Bounds.GetSize().GetMax(), 1.f);
	Part->SetRelativeScale3D(FVector(Scale));
	Part->SetRelativeRotation(FRotator(0.0, Yaw, 0.0));
	// Stand the model on Location: the bottom of its box, not its pivot.
	Part->SetRelativeLocation(Location - FRotator(0.0, Yaw, 0.0).RotateVector(FVector(Bounds.GetCenter().X, Bounds.GetCenter().Y, Bounds.Min.Z)) * Scale);
	Parts.Add(Part);
	PartPieces.Add(Piece);
	return Part;
}

